users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
// Fetch availability for all users on all dates concurrently
avails = for u in users {
    by_date = for d in dates {
        a = boundary retry 2 {
            return get_availability({ user_id: u.id, date: d })
        } catch err {
            return fail("AVAIL", err.code + ": " + err.message)
        }
        return { date: d, busy: a.busy if a.busy != null else [] }
    }
    return { user_id: u.id, days: by_date }
}
return { users: users, avails: avails }

// Availability data from previous fetch
avails = [
  {user_id: "U1", days: [
    {date: "2026-06-15", busy: [{start: "09:00", end: "12:00"}]},
    {date: "2026-06-16", busy: [{start: "13:00", end: "17:00"}]},
    {date: "2026-06-17", busy: [{start: "09:00", end: "11:00"}]},
    {date: "2026-06-18", busy: [{start: "09:00", end: "09:30"}]},
    {date: "2026-06-19", busy: []}
  ]},
  {user_id: "U2", days: [
    {date: "2026-06-15", busy: [{start: "11:30", end: "15:00"}]},
    {date: "2026-06-16", busy: [{start: "09:00", end: "13:30"}]},
    {date: "2026-06-17", busy: [{start: "10:30", end: "14:00"}]},
    {date: "2026-06-18", busy: []},
    {date: "2026-06-19", busy: []}
  ]},
  {user_id: "U3", days: [
    {date: "2026-06-15", busy: [{start: "14:30", end: "17:00"}]},
    {date: "2026-06-16", busy: []},
    {date: "2026-06-17", busy: [{start: "09:00", end: "10:00"}]},
    {date: "2026-06-18", busy: []},
    {date: "2026-06-19", busy: [{start: "16:00", end: "17:00"}]}
  ]},
  {user_id: "U4", days: [
    {date: "2026-06-15", busy: [{start: "10:00", end: "11:00"}]},
    {date: "2026-06-16", busy: [{start: "11:00", end: "12:00"}]},
    {date: "2026-06-17", busy: [{start: "15:30", end: "16:30"}]},
    {date: "2026-06-18", busy: []},
    {date: "2026-06-19", busy: []}
  ]}
]

// Convert HH:MM to minutes since midnight
to_min = fun(t) {
  parts = text.split(t, ":")
  return number.parse(parts[0]) * 60 + number.parse(parts[1])
}

// Possible starts: 09:00 to 16:00 inclusive, every 30 min
starts = list.range(9 * 60, 16 * 60 + 1, 30)

dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

// For each date and start, check if all free
slots = fold acc = null for d in dates {
  skip if acc != null
  found = fold inner = null for s in starts {
    skip if inner != null
    end_m = s + 60
    // Check all users free for [s, end_m)
    conflicts = for u in avails {
      day = fold dd = null for day in u.days {
        skip if day.date != d
        return day
      }
      busy_list = day.busy if day != null else []
      hit = fold h = false for b in busy_list {
        skip if h
        bs = to_min(b.start)
        be = to_min(b.end)
        // overlap if bs < end_m and be > s
        ov = bs < end_m and be > s
        return ov
      }
      skip if not hit
      return true
    }
    free = list.length(conflicts) == 0
    skip if not free
    // format
    sh = number.floor(s / 60)
    sm = s - sh * 60
    eh = number.floor(end_m / 60)
    em = end_m - eh * 60
    shs = text.slice("0" + json.encode(sh), -2, 100)
    sms = text.slice("0" + json.encode(sm), -2, 100)
    ehs = text.slice("0" + json.encode(eh), -2, 100)
    ems = text.slice("0" + json.encode(em), -2, 100)
    return { start: d + "T" + shs + ":" + sms + ":00Z", end: d + "T" + ehs + ":" + ems + ":00Z" }
  }
  return found
}

assert(slots != null, "no slot found")
_ = submit_result({ answer: slots })
return slots

