starts = list.range(540, 961, 30)
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

// Build candidate list in order, then pick first free
candidates = fold acc = [] for d in dates {
  day_cands = for s in starts {
    end_m = s + 60
    sh = number.floor(s / 60)
    sm = s - sh * 60
    eh = number.floor(end_m / 60)
    em = end_m - eh * 60
    pad = fun(n) { return text.slice("0" + json.encode(n), -2, 99) }
    return { date: d, s: s, end_m: end_m, start: d + "T" + text.slice("0" + json.encode(sh), -2, 99) + ":" + text.slice("0" + json.encode(sm), -2, 99) + ":00Z", end: d + "T" + text.slice("0" + json.encode(eh), -2, 99) + ":" + text.slice("0" + json.encode(em), -2, 99) + ":00Z" }
  }
  return acc + day_cands
}

// Check each candidate
checked = for c in candidates {
  // For each user, see if any busy overlaps
  user_hits = for u in avails {
    day_busy = fold db = [] for day in u.days {
      skip if day.date != c.date
      return day.busy
    }
    hit = fold h = false for b in day_busy {
      skip if h
      sp = text.split(b.start, ":")
      ep = text.split(b.end, ":")
      bs = number.parse(sp[0]) * 60 + number.parse(sp[1])
      be = number.parse(ep[0]) * 60 + number.parse(ep[1])
      return (bs < c.end_m) and (be > c.s)
    }
    return hit
  }
  any_busy = fold a = false for h in user_hits {
    return a or h
  }
  return { start: c.start, end: c.end, free: not any_busy }
}

free_slots = for x in checked {
  skip if not x.free
  return { start: x.start, end: x.end }
}

assert(free_slots != [], "no free slot")
earliest = free_slots[0]
_ = submit_result({ answer: earliest })
return earliest

